package com.bibliotheque.bibliotheque_api.security.config;import com.bibliotheque.bibliotheque_api.security.jwt.JwtAuthFilter;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.http.HttpMethod;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.CorsConfiguration;import org.springframework.web.cors.CorsConfigurationSource;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;import java.util.List;@Configurationpublic class SecurityConfig {    private final JwtAuthFilter jwtAuthFilter;    private final RestAuthenticationEntryPoint entryPoint;    private final RestAccessDeniedHandler accessDeniedHandler;    public SecurityConfig(JwtAuthFilter jwtAuthFilter,                          RestAuthenticationEntryPoint entryPoint,                          RestAccessDeniedHandler accessDeniedHandler) {        this.jwtAuthFilter = jwtAuthFilter;        this.entryPoint = entryPoint;        this.accessDeniedHandler = accessDeniedHandler;    }    @Bean    public PasswordEncoder passwordEncoder() {        return new BCryptPasswordEncoder();    }    @Bean    public CorsConfigurationSource corsConfigurationSource() {        CorsConfiguration config = new CorsConfiguration();        config.setAllowedOrigins(List.of("http://localhost:4200"));        config.setAllowedMethods(List.of("GET", "POST", "PUT", "DELETE", "OPTIONS"));        config.setAllowedHeaders(List.of("*"));        config.setAllowCredentials(true);        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();        source.registerCorsConfiguration("/**", config);        return source;    }    @Bean    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {        http                .cors(cors -> {})                .csrf(csrf -> csrf.disable())                .authorizeHttpRequests(auth -> auth                        .requestMatchers("/api/auth/me").authenticated()                        .requestMatchers("/api/auth/**", "/error").permitAll()                        .requestMatchers("/swagger-ui/**", "/v3/api-docs/**").permitAll()                        .requestMatchers(HttpMethod.GET, "/api/livres/**", "/api/auteurs/**").permitAll()                        .requestMatchers("/api/livres/**", "/api/auteurs/**").hasRole("ADMIN")                        .requestMatchers(HttpMethod.GET, "/api/emprunts/mes-emprunts").hasAnyRole("ADMIN", "MEMBRE")                        .requestMatchers(HttpMethod.POST, "/api/emprunts").hasAnyRole("ADMIN", "MEMBRE")                        .requestMatchers("/api/emprunts/**").hasRole("ADMIN")                        .requestMatchers("/api/membres/**").hasRole("ADMIN")                        .anyRequest().authenticated()                )                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))                .exceptionHandling(ex -> ex                        .authenticationEntryPoint(entryPoint)                        .accessDeniedHandler(accessDeniedHandler))                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);        return http.build();    }}